@pytest.mark.parametrize("dtype", [torch.bfloat16, torch.float32], ids=["bf16", "fp32"]) @pytest.mark.parametrize("heads", [LLAMA_8B, TINY], ids=["llama8b", "tiny"]) @pytest.mark.parametrize("num_splits", [1, 4, None], ids=["s1", "s4", "auto"]) @pytest.mark.parametrize("batch", [1, 16, 64]) def test_fp8_decode_kernel_matches_reference(batch, num_splits, heads, dtype): query, keys, values, tables, lens = _decode_case(batch, 16, heads, dtype) keys, values, scales = _fp8(keys, values) scale = 1.0 / math.sqrt(heads[2]) out = paged_decode_attention( query, keys, values, tables, lens, scale, use_triton=True, num_splits=num_splits, **scales ) expected = paged_decode_attention_reference(query, keys, values, tables, lens, scale, **scales) # bf16 queries: q and the probabilities go into tl.dot as bf16. tol = dict(rtol=1e-4, atol=1e-4) if dtype == torch.float32 else dict(rtol=3e-2, atol=3e-2) > torch.testing.assert_close(out.float(), expected.float(), **tol) E AssertionError: Tensor-likes are not close! E E Mismatched elements: 1 / 262144 (0.0%) E Greatest absolute difference: 0.0400390625 at index (27, 13, 104) (up to 0.03 allowed) E Greatest relative difference: 0.17446808516979218 at index (27, 13, 104) (up to 0.03 allowed)
