page_size = 4, heads = (32, 8, 128), dtype = torch.bfloat16
@pytest.mark.parametrize("dtype", [torch.bfloat16, torch.float32], ids=["bf16", "fp32"]) @pytest.mark.parametrize("heads", [LLAMA_8B, TINY], ids=["llama8b", "tiny"]) @pytest.mark.parametrize("page_size", [4, 16]) def test_fp8_prefill_kernel_matches_reference(page_size, heads, dtype): q_heads, kv_heads, head_dim = heads query_lens = [q for q, _ in PREFILL_SHAPES] context_lens = [c for _, c in PREFILL_SHAPES] num_blocks = sum((c + page_size - 1) // page_size for c in context_lens) + 4 keys, values, scales = _fp8(*_cache(num_blocks, page_size, kv_heads, head_dim, dtype)) tables = _shuffled_tables(context_lens, page_size, num_blocks) query = torch.randn(sum(query_lens), q_heads, head_dim, device="cuda").to(dtype) cu_seqlens = torch.tensor([0] + query_lens, device="cuda").cumsum(0).to(torch.int32) lens = torch.tensor(context_lens, dtype=torch.int32, device="cuda") scale = 1.0 / math.sqrt(head_dim) out = paged_prefill_attention( query, keys, values, tables, cu_seqlens, lens, query_lens, context_lens, scale, use_triton=True, **scales, ) expected = paged_prefill_attention_reference( query, keys, values, tables, query_lens, context_lens, scale, **scales ) tol = dict(rtol=1e-4, atol=1e-4) if dtype == torch.float32 else dict(rtol=3e-2, atol=3e-2) > torch.testing.assert_close(out.float(), expected.float(), **tol) E AssertionError: Tensor-likes are not close! E E Mismatched elements: 9 / 2007040 (0.0%) E Greatest absolute difference: 0.05859375 at index (257, 31, 60) (up to 0.03 allowed) E Greatest relative difference: 2.625570774078369 at index (179, 20, 67) (up to 0.03 allowed)
